    std::uint8_t *aEarthLaneB = pWorkSpace->mEarthLaneB;
    std::uint8_t *aEarthLaneC = pWorkSpace->mEarthLaneC;
    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0x95390C5651895E27ULL + 0x91824DB0071BDF20ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseC(pNonce * 0xA8D9BA9AB69FB82DULL + 0xF003D4ADF163E879ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseB(pNonce * 0xB2DD5C02E8B350C5ULL + 0xC20E6F168929C697ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseB(pNonce * 0x8BA196C5E214A26DULL + 0xF1FFCC641E725978ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseB(pNonce * 0xA0681CB4F8D50FC7ULL + 0xD834F062F3A47685ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseC(pNonce * 0xE9D49F7B7509CFFBULL + 0x85098BA043ECFBE3ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseC(pNonce * 0xAEBB415CC2ED6EB1ULL + 0xB34265717F288305ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordH = TwistMix64::DiffuseC(pNonce * 0xC75917077C1AA8A1ULL + 0xD57A1FCE23E85107ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordI = TwistMix64::DiffuseA(pNonce * 0xC6A38DEC8C08812DULL + 0xE51A59994CBC084BULL);
    [[maybe_unused]] const std::uint64_t aNonceWordJ = TwistMix64::DiffuseB(pNonce * 0x9FD16EF903139CE5ULL + 0xE50B544878DB24CFULL);
    [[maybe_unused]] const std::uint64_t aNonceWordK = TwistMix64::DiffuseB(pNonce * 0xFB325E0804AE64A1ULL + 0xB59CE74D0A27D435ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordL = TwistMix64::DiffuseB(pNonce * 0xB8FF3DD2FA4B163BULL + 0xE26C31BB69580C1FULL);
    [[maybe_unused]] const std::uint64_t aNonceWordM = TwistMix64::DiffuseC(pNonce * 0xA0339BB025D90BDBULL + 0xB545FA3177C033C9ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordN = TwistMix64::DiffuseC(pNonce * 0xF75BBDE3AAEDC0E5ULL + 0xF981CE57C8279FC2ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordO = TwistMix64::DiffuseA(pNonce * 0x8EE492A95FE6BC47ULL + 0xC1AAFC7F2F970F31ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordP = TwistMix64::DiffuseB(pNonce * 0xD82C043372B8D3CFULL + 0xEAE0849DFF544770ULL);
    std::uint64_t aDomainWordIngress = pConstants->mIngress;
    std::uint64_t aDomainWordScatter = pConstants->mScatter;
    std::uint64_t aDomainWordCross = pConstants->mCross;
    std::uint8_t *aSource = pWorkSpace->mSource;
    std::uint64_t aPrevious = *pPrevious;
    std::uint64_t aIngress = *pIngress;
    std::uint64_t aCarry = *pCarry;
    std::uint64_t aWandererA = *pWandererA;
