            aOrbiterH = ((aOrbiterH ^ aOrbiterJ) ^ 0x921F742E3B6065EAULL) ^ aNonceWordM;
            aOrbiterH = RotL64((aOrbiterH * 0xE13F38D0FD8DC45BULL), 21U);
            //
