            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x376742EC9949B09FULL;
            aOrbiterB = RotL64((aOrbiterB * 0xED414973D5BCFCD3ULL), 29U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x3EF3F9ECFBC5C219ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0xD0A925CEDAED716CULL;
            aOrbiterI = RotL64((aOrbiterI * 0xB0450501050C5663ULL), 41U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0x8FB14A27379F6B1CULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0x6B4BE330CAED62E9ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xBD3A9E85672E5A7BULL), 27U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0x8D40853995808F67ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterI) ^ 0x56152973E18A122CULL;
