            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0x69FCA08AF41456B6ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterA) ^ 0xE5B9A3F08956AEC3ULL) ^ aSeedOrbiterUpdateSaltB[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x4515A07656AD4C15ULL), 35U);
