            aCarry = aCarry + (RotL64(aWandererJ, 26U) ^ aWandererH);
            aCarry = aCarry + (aWandererC ^ RotL64(aWandererG, 3U));
            aCarry = aCarry + (aWandererA ^ RotL64(aWandererF, 29U));
            aCarry = aCarry + (RotL64(aWandererD, 51U) ^ aWandererB);
            aCarry = aCarry + (aWandererE ^ RotL64(aWandererI, 6U));
            aCarry = aCarry + RotL64(aWandererK, 53U);
            aCarry = aCarry + RotL64(aIngress, 13U);
