            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterK = (((aWandererD + RotL64(aIngress, 35U)) + RotL64(aCarry, 43U)) + 0x3F7A51F09642A27CULL) + aTwistOrbiterAssignSaltD[((aIndex + 24U)) & S_SALT1];
