            aOrbiterC = ((aWandererE + RotL64(aCross, 57U)) + RotL64(aCarry, 27U)) + 0xFC0816A320EBF8E5ULL;
            aOrbiterH = ((aWandererG + RotL64(aPrevious, 19U)) + 0xDE273D732D867B09ULL) + aTwistOrbiterAssignSaltC[((aIndex + 9U)) & S_SALT1];
            aOrbiterG = (aWandererC + RotL64(aIngress, 27U)) + 0x964C1755764B9E3AULL;
