            //
            aOrbiterB = ((aOrbiterB + aOrbiterF) + 0xFC1E26EC584B71D5ULL) + aTwistOrbiterUpdateSaltC[((aIndex + 17U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterB) ^ 0x3B540E6AE9F35711ULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x50A7B66EBFA778A5ULL), 11U);
