            //
            aWandererI = aWandererI ^ (((RotL64(aScatter, 57U) + RotL64(aOrbiterC, 57U)) + aOrbiterG) + aTwistWandererUpdateSaltB[((aIndex + 25U)) & S_SALT1]);
