            aWandererC = aWandererC + ((RotL64(aCross, 29U) + RotL64(aOrbiterG, 41U)) + aOrbiterE);
            aWandererD = aWandererD ^ (((RotL64(aScatter, 5U) + aOrbiterB) + RotL64(aOrbiterF, 19U)) + aTwistWandererUpdateSaltF[((aIndex + 26U)) & S_SALT1]);
            //
