            aOrbiterE = (aWandererD + RotL64(aIngress, 29U)) + 0x98AC6E3AE77E78ECULL;
            aOrbiterI = ((aWandererA + RotL64(aPrevious, 54U)) + RotL64(aCarry, 39U)) + 0x3D6C242E5C39DBA4ULL;
            aOrbiterD = (aWandererI + RotL64(aScatter, 21U)) + 0x061623A79F868CFBULL;
            aOrbiterA = (aWandererG + RotL64(aCross, 43U)) + 0x31D58D2AE70F3371ULL;
            aOrbiterF = (aWandererK + RotL64(aScatter, 37U)) + 0x9F9773D40A303184ULL;
            aOrbiterH = (((aWandererB + RotL64(aIngress, 5U)) + RotL64(aCarry, 51U)) + 0xB18160F7F0EDDCBEULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterJ = (((aWandererJ + RotL64(aCross, 11U)) + RotL64(aCarry, 3U)) + 0x7015D75A4E475CFDULL) + aTwistOrbiterAssignSaltE[((aIndex + 7U)) & S_SALT1];
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0xEB60BEDCD3433AC9ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterE) ^ 0x55E71D86952AA055ULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 16U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xE28A37306D27D40FULL), 35U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x47BCBCF9280CB0F7ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0x830B8340EC94A41BULL;
            aOrbiterF = RotL64((aOrbiterF * 0xC3E2F04B3EA5B697ULL), 13U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0xD990EBB63C61548CULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0x56846EAB555652A2ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x57CCA2BCF7029133ULL), 27U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x89811AF94B08556CULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0x9F0F1E59693631D2ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xCB7AAA3D8B752309ULL), 19U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0xC73A7774DC330EEFULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterF) ^ 0x4F3BB53F6F709963ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x5EDC12AC2BCC090FULL), 51U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterF) + 0xDB649BECBBBDC55DULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterH) ^ 0xD959DC958CEAE66CULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 5U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x0C3E9D6F0C098E9BULL), 57U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterE) + 0x0665F6A1925A4553ULL) + aTwistOrbiterUpdateSaltF[((aIndex + 3U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0xCEA98CEB3BA797C6ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xEA8D1A6F115B0D8BULL), 41U);
            //
            aIngress = RotL64(aOrbiterH, 36U) ^ aOrbiterD;
            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterF, 51U));
