            aWandererD = aWandererD ^ (((RotL64(aScatter, 57U) + aOrbiterJ) + RotL64(aOrbiterD, 51U)) + aTwistWandererUpdateSaltE[(((31U - aIndex) + 29U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aCross, 5U) + aOrbiterA) + RotL64(aOrbiterI, 13U)) + RotL64(aCarry, 37U));
            aWandererA = aWandererA ^ ((RotL64(aIngress, 47U) + aOrbiterJ) + RotL64(aOrbiterE, 3U));
            aWandererG = aWandererG + (((RotL64(aPrevious, 11U) + aOrbiterF) + RotL64(aOrbiterJ, 44U)) + RotL64(aCarry, 57U));
