            aWandererI = aWandererI + (((RotL64(aCross, 21U) + aOrbiterF) + RotL64(aOrbiterA, 57U)) + aTwistWandererUpdateSaltA[(((31U - aIndex) + 14U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 28U) + RotL64(aOrbiterI, 37U)) + aOrbiterH);
