            aOrbiterJ = RotL64((aOrbiterJ * 0xAA03B0EABD19573BULL), 53U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterK) + 0x4BBFBAF14CC4BB6FULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterJ) ^ 0x2F6D25B22B218631ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 22U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x974A1D0AF29A672DULL), 41U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0xE861651B757BB6C6ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterI) ^ 0xEBBFBB23B28B538EULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x0357EC6155542EE1ULL), 5U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterE) + 0x2FDFA4CE34074E8EULL) + aTwistOrbiterUpdateSaltE[((aIndex + 27U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0x65B5FB7E2A88FE7FULL;
            aOrbiterF = RotL64((aOrbiterF * 0x3ABABA9D3B9106D1ULL), 47U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0x1D5CCD3E1B09C1EFULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0x649A5B0608A17652ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x943939C6D8915CE7ULL), 19U);
