            //
            aWandererB = aWandererB ^ (((RotL64(aScatter, 46U) + RotL64(aOrbiterH, 27U)) + aOrbiterJ) + aTwistWandererUpdateSaltD[(((31U - aIndex) + 26U)) & S_SALT1]);
            aWandererD = aWandererD + (((RotL64(aIngress, 13U) + RotL64(aOrbiterH, 5U)) + aOrbiterI) + RotL64(aCarry, 27U));
            aWandererG = aWandererG ^ ((RotL64(aPrevious, 29U) + RotL64(aOrbiterH, 11U)) + aOrbiterE);
            aWandererE = aWandererE + ((RotL64(aCross, 19U) + aOrbiterI) + RotL64(aOrbiterD, 19U));
            aWandererF = aWandererF ^ ((RotL64(aPrevious, 35U) + aOrbiterH) + RotL64(aOrbiterD, 50U));
            aWandererH = aWandererH + ((((RotL64(aScatter, 5U) + RotL64(aOrbiterK, 43U)) + aOrbiterF) + RotL64(aCarry, 5U)) + aTwistWandererUpdateSaltC[((aIndex + 10U)) & S_SALT1]);
            aWandererA = aWandererA ^ ((RotL64(aCross, 57U) + RotL64(aOrbiterI, 35U)) + aOrbiterF);
