            //
            aOrbiterI = ((aWandererD + RotL64(aIngress, 47U)) + RotL64(aCarry, 19U)) + 0x8420D1B5B02920DCULL;
            aOrbiterB = ((aWandererB + RotL64(aCross, 53U)) + 0x0DF5C7165F9DB1DBULL) + aTwistOrbiterAssignSaltE[((aIndex + 23U)) & S_SALT1];
