            aOrbiterD = (aWandererJ + RotL64(aIngress, 3U)) + 0x9842227F5C910586ULL;
            aOrbiterG = (((aWandererH + RotL64(aCross, 13U)) + RotL64(aCarry, 3U)) + 0xE02D9B0A86F23845ULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterH = (aWandererG + RotL64(aPrevious, 19U)) + 0x8B425FD6C5EB4318ULL;
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0x57A63F231F20C308ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0x3C77688E643078C7ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x0E6BD78577623CDFULL), 3U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x7448782E2062232AULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0x268BF594B5CC9C43ULL;
