            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0xE0A7F42763723797ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterD) ^ 0x487367F60DF60A86ULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 4U)) & S_SALT1];
