            //
            aOrbiterB = ((aOrbiterB + aOrbiterG) + 0x9A2781745F03E67BULL) + aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x467546FE519F28CBULL;
