            aIngress ^= (RotL64(aEarthLaneA[((aIndex + 8863U)) & S_BLOCK1], 11U) ^ RotL64(aEarthLaneD[((aIndex + 10794U)) & S_BLOCK1], 3U));
            aIngress = TwistMix64::DiffuseC(aIngress);
