            aCross ^= (RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 15882U)) & S_BLOCK1], 57U) ^ RotL64(aEarthLaneB[((S_BLOCK1 - aIndex + 8805U)) & S_BLOCK1], 46U));
            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aCross, 53U) + RotL64(aIngress, 27U)) ^ (RotL64(aCarry, 10U) ^ RotL64(aPrevious, 41U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterK = (aWandererK + RotL64(aPrevious, 43U)) + 0x1F0C44342A943CF4ULL;
            aOrbiterG = ((aWandererJ + RotL64(aScatter, 51U)) + 0xA391DB429DC10C73ULL) + aTwistOrbiterAssignSaltC[((aIndex + 9U)) & S_SALT1];
            aOrbiterF = ((aWandererF + RotL64(aIngress, 3U)) + RotL64(aCarry, 41U)) + 0x845CF4F5CFAACA3EULL;
            aOrbiterI = (aWandererD + RotL64(aCross, 21U)) + 0x4C8C6D42206329DCULL;
            aOrbiterC = ((aWandererA + RotL64(aPrevious, 37U)) + RotL64(aCarry, 53U)) + 0xD34DBCBEB0AC0CA9ULL;
            aOrbiterE = (((aWandererE + RotL64(aCross, 12U)) + RotL64(aCarry, 5U)) + 0x4AD9C4DF901409BBULL) + aTwistOrbiterAssignSaltF[((aIndex + 6U)) & S_SALT1];
            aOrbiterH = (aWandererC + RotL64(aIngress, 57U)) + 0x82BD0A8B3FA4DB64ULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x22CF87E84D08419AULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0x0DC6A6A8A8564F6BULL;
            aOrbiterF = RotL64((aOrbiterF * 0x215EB5FB3664B481ULL), 47U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterK) + 0xCB59352B65A10F76ULL) + aTwistOrbiterUpdateSaltB[((aIndex + 17U)) & S_SALT1];
