            aOrbiterC = RotL64((aOrbiterC * 0xAA848260F83EA989ULL), 5U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0xA68BC7381A3823FBULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterF) ^ 0x880E33F496CAEA73ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xAC74137B5E2AA321ULL), 29U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterI) + 0x0855D2DD6D719581ULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0x5A6AD7CEF7E71DA8ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xC643C396DDB6C501ULL), 23U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0xFC43558D1CD15094ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0xC627D9E80A45BDEBULL;
            aOrbiterH = RotL64((aOrbiterH * 0xF04E7216D28F5155ULL), 57U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterH) + 0xE22A5D6AD9243B40ULL) + aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0xE8799713BF4DD476ULL;
