            aOrbiterI = RotL64((aOrbiterI * 0x66BF86796FAC44CBULL), 11U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0xB9F6A420905C6FB8ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterD) ^ 0xE190111758451313ULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x457BB358C58753BDULL), 37U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0x88DACBD9E2D3882CULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0xD9EA64A56A7E18F6ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x8A5F4E2DA596F7D1ULL), 19U);
