            //
            aWandererK = aWandererK ^ ((RotL64(aScatter, 43U) + aOrbiterB) + RotL64(aOrbiterC, 23U));
            aWandererC = aWandererC + (((RotL64(aPrevious, 21U) + aOrbiterJ) + RotL64(aOrbiterK, 27U)) + aTwistWandererUpdateSaltD[(((31U - aIndex) + 27U)) & S_SALT1]);
