            aWandererH = aWandererH ^ (((RotL64(aPrevious, 13U) + RotL64(aOrbiterG, 50U)) + aOrbiterA) + aTwistWandererUpdateSaltE[((aIndex + 7U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererH, 52U) ^ aWandererA);
            aCarry = aCarry + (aWandererI ^ RotL64(aWandererK, 41U));
            aCarry = aCarry + (RotL64(aWandererG, 19U) ^ aWandererD);
