            aOrbiterD = ((aWandererG + RotL64(aPrevious, 36U)) + RotL64(aCarry, 23U)) + 0x13C584EC297482F4ULL;
            aOrbiterC = ((aWandererD + RotL64(aCross, 5U)) + RotL64(aCarry, 37U)) + 0x24193A03A79A2D5DULL;
            aOrbiterB = (aWandererK + RotL64(aScatter, 43U)) + 0x171246C2E6532CD9ULL;
            aOrbiterE = ((aWandererA + RotL64(aIngress, 11U)) + RotL64(aCarry, 5U)) + 0x833A53D114E46651ULL;
            aOrbiterA = (aWandererI + RotL64(aCross, 23U)) + 0x4884F22153E22CCEULL;
            aOrbiterI = ((aWandererC + RotL64(aIngress, 29U)) + 0x92B11CEE320875A5ULL) + aTwistOrbiterAssignSaltA[((aIndex + 8U)) & S_SALT1];
            aOrbiterF = ((aWandererF + RotL64(aScatter, 53U)) + 0xE4B3BDC2F9AEC5B4ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 28U)) & S_SALT1];
