            //
            aOrbiterG = ((aOrbiterG + aOrbiterC) + 0x5B435ED880D68C8AULL) + aTwistOrbiterUpdateSaltF[((aIndex + 3U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x4DBAB26A0C281EFDULL;
            aOrbiterB = RotL64((aOrbiterB * 0xBB13DA7C53C74F8FULL), 51U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterB) + 0x3DBE7298FEC53CCCULL) + aTwistOrbiterUpdateSaltD[((aIndex + 15U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0x07E080A3725DDF97ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x717D60D5F838A0A9ULL), 57U);
            //
            aIngress = RotL64(aOrbiterC, 29U) ^ aOrbiterJ;
