            aWandererA = aWandererA ^ ((RotL64(aPrevious, 60U) + RotL64(aOrbiterC, 19U)) + aOrbiterF);
            aWandererD = aWandererD + ((((RotL64(aCross, 53U) + RotL64(aOrbiterK, 6U)) + aOrbiterE) + RotL64(aCarry, 29U)) + aTwistWandererUpdateSaltD[((aIndex + 16U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 5U) + aOrbiterE) + RotL64(aOrbiterJ, 35U));
