            aOrbiterB = ((aWandererF + RotL64(aScatter, 51U)) + 0x89E9219780E6834DULL) + aTwistOrbiterAssignSaltF[((aIndex + 9U)) & S_SALT1];
            aOrbiterC = ((aWandererK + RotL64(aPrevious, 35U)) + RotL64(aCarry, 21U)) + 0xC697D58F4C9BD320ULL;
