            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x4E85064C1646C84EULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterA) ^ 0x2C1C3C6A735C7114ULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xBA647AE35F659C33ULL), 21U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0xD5DF9ECE2C1ED2C5ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0xCC659C0D7BE302B6ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x862D9C1B173C961DULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0x4F73087830212B6FULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x3D0B88A15D7EE3BAULL;
            aOrbiterG = RotL64((aOrbiterG * 0xB4C8D7F4E8147D9FULL), 11U);
