            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x1D1393DBD57B820AULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterB) ^ 0xFAE195C2FA9EAA10ULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 12U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x6F2749B1CA769195ULL), 5U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0xA38A96F690D77D5CULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterH) ^ 0x379DB95451FCDE79ULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 23U)) & S_SALT1];
