            aOrbiterF = (((aWandererF + RotL64(aCross, 18U)) + RotL64(aCarry, 29U)) + 0xB6EDECB0F38EA534ULL) + aTwistOrbiterAssignSaltC[((aIndex + 26U)) & S_SALT1];
