            aOrbiterE = (aWandererG + RotL64(aPrevious, 53U)) + 0x52EF6852D5153ECBULL;
            aOrbiterD = ((aWandererC + RotL64(aIngress, 13U)) + RotL64(aCarry, 43U)) + 0x9D3242F4B5D4CD97ULL;
            aOrbiterK = (aWandererK + RotL64(aCross, 48U)) + 0x37454499777B952AULL;
