            //
            aIngress = (RotL64(aPoisonLaneA[((aIndex + 2564U)) & S_BLOCK1], 60U) ^ RotL64(aPoisonLaneB[((aIndex + 4690U)) & S_BLOCK1], 21U));
            aIngress ^= (RotL64(aKeyRowReadA[((aIndex + 2606U)) & W_KEY1], 47U) ^ RotL64(aLightningLaneA[((aIndex + 7877U)) & S_BLOCK1], 39U));
            aIngress = TwistMix64::DiffuseC(aIngress);
            //
            aCross = (RotL64(aPoisonLaneC[((S_BLOCK1 - aIndex + 6903U)) & S_BLOCK1], 44U) ^ RotL64(aWaterLaneA[((S_BLOCK1 - aIndex + 2109U)) & S_BLOCK1], 3U));
            aCross ^= (RotL64(aWoodLaneC[((S_BLOCK1 - aIndex + 2756U)) & S_BLOCK1], 23U) ^ RotL64(aKeyRowReadB[(((2047U - aIndex) + 8057U)) & W_KEY1], 35U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aIngress, 3U) + RotL64(aCarry, 35U)) + (RotL64(aCross, 19U) ^ RotL64(aPrevious, 48U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterF = ((aWandererJ + RotL64(aScatter, 43U)) + RotL64(aCarry, 57U)) + 0xDD91B2DC937D68F8ULL;
            aOrbiterJ = (aWandererB + RotL64(aIngress, 29U)) + 0x98434562BA0448C0ULL;
            aOrbiterD = (aWandererI + RotL64(aCross, 57U)) + 0x46A7D78C9E62F599ULL;
            aOrbiterA = (aWandererD + RotL64(aPrevious, 20U)) + 0x353B6769C6566069ULL;
            aOrbiterK = ((aWandererC + RotL64(aIngress, 13U)) + RotL64(aCarry, 43U)) + 0x4998AB473154DB13ULL;
            aOrbiterG = (((aWandererF + RotL64(aCross, 51U)) + RotL64(aCarry, 19U)) + 0xD561C4DECF4F7A1CULL) + aKeyRotateOrbiterAssignSaltD[((aIndex + 14U)) & S_SALT1];
            aOrbiterE = ((aWandererK + RotL64(aPrevious, 37U)) + 0xE1ADCA5BA0AE12DAULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 8U)) & S_SALT1];
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0xDF52E1F78228B033ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0xEED8D8C27C391674ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x08E2435907862AD7ULL), 3U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0xF3E56B1CD153B697ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterD) ^ 0xC9D83023DCC13249ULL) ^ aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 27U)) & S_SALT1];
