            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0xD1147D462959F7DBULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x89F933BD68F65F17ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x5AB928E280F956A5ULL), 37U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0x65DE5552E1905F40ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0x38962DFB326AE583ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xC958F9FCB0CBC35DULL), 11U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x3CE12727035989C7ULL;
