            aOrbiterJ = RotL64((aOrbiterJ * 0x8C4896CB2D61A723ULL), 43U);
            //
            aIngress = RotL64(aOrbiterE, 3U) ^ aOrbiterK;
            aIngress = aIngress + (aOrbiterG ^ RotL64(aOrbiterF, 41U));
            aIngress = aIngress + (RotL64(aOrbiterD, 35U) ^ aOrbiterJ);
