            //
            aWandererF = aWandererF + ((((RotL64(aIngress, 51U) + RotL64(aOrbiterE, 47U)) + aOrbiterK) + RotL64(aCarry, 29U)) + aKeyRotateWandererUpdateSaltC[((aIndex + 5U)) & S_SALT1]);
