            aIngress ^= (RotL64(aMagmaLaneB[((aIndex + 13564U)) & S_BLOCK1], 37U) ^ RotL64(aMagmaLaneC[((aIndex + 12005U)) & S_BLOCK1], 51U));
            aIngress = TwistMix64::DiffuseB(aIngress);
