            aOrbiterJ = RotL64((aOrbiterJ * 0x2AD5697611325D6FULL), 27U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0x3A57666E19448087ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0x026764BE3D14B822ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x2B1A4DEC71E89BBDULL), 11U);
