            aOrbiterK = ((aOrbiterK + aOrbiterJ) + 0x31EE741A4B77C85AULL) + aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x8A52E6CA7A44ADA6ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xF3A37B490C574A23ULL), 41U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0xA6FE3219D2D8CC8AULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterE) ^ 0xF0FC92184DF62C15ULL) ^ aKeyRotateOrbiterUpdateSaltD[((aIndex + 7U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xC7D0A5A450784E0FULL), 57U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterE) + 0x9C7B36824F72F049ULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 20U)) & S_SALT1];
