            aWandererB = aWandererB ^ (((RotL64(aIngress, 39U) + aOrbiterG) + RotL64(aOrbiterJ, 5U)) + aKeyRotateWandererUpdateSaltE[(((31U - aIndex) + 25U)) & S_SALT1]);
            aWandererE = aWandererE + ((((RotL64(aScatter, 53U) + RotL64(aOrbiterE, 13U)) + aOrbiterD) + RotL64(aCarry, 35U)) + aKeyRotateWandererUpdateSaltB[(((31U - aIndex) + 9U)) & S_SALT1]);
