            aOrbiterE = (aWandererB + RotL64(aIngress, 43U)) + 0xA1A3A92B55142E49ULL;
            aOrbiterI = ((aWandererG + RotL64(aScatter, 36U)) + RotL64(aCarry, 39U)) + 0x1E22E71DBACF7084ULL;
            aOrbiterH = ((aWandererA + RotL64(aPrevious, 27U)) + 0x2B5672880CC935B6ULL) + aKeySpawnOrbiterAssignSaltC[(((31U - aIndex) + 11U)) & S_SALT1];
