            aOrbiterG = (aWandererD + RotL64(aIngress, 23U)) + 0xEA5DD3F4B84D4657ULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0xA05D5CC74702BBEFULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterF) ^ 0x94FE2BD4BD6C462EULL) ^ aKeySpawnOrbiterUpdateSaltA[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x7DCE9F5AF8C09643ULL), 47U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0xA32F42C6CB6653B0ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterH) ^ 0x2D56A08B0C33B9C1ULL) ^ aKeySpawnOrbiterUpdateSaltF[((aIndex + 12U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xBE02FB4D75A29C6DULL), 5U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterI) + 0x13EE11148CA9E73EULL) + aKeySpawnOrbiterUpdateSaltD[((aIndex + 23U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0xBF3E9B6F11D3CA51ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x7D2303F08E4E8B07ULL), 23U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0xF1059E273106B913ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0x670553CEB74F9AECULL;
            aOrbiterC = RotL64((aOrbiterC * 0x033B6A03CC0F29FBULL), 51U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0x96CE916875BFB62EULL;
