            aOrbiterA = RotL64((aOrbiterA * 0x9DCB2D52B73E7D13ULL), 3U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x539B5836556CCE89ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x20D95C3509F043CFULL;
            aOrbiterH = RotL64((aOrbiterH * 0xCDE774A8C148E4F5ULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0xF20C69D905E9C68BULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0x33BD8AE21AF19163ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xB3C9F66026D92D69ULL), 19U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterD) + 0xC2970F3730F27C59ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0xE5BDB8155A2BA355ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xE4619AF82406EC5BULL), 27U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0x732C06D86C6EE78FULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0xEDF893DE68F04521ULL;
