            //
            aOrbiterC = (aWandererE + RotL64(aIngress, 29U)) + 0x9461C9CC8F13E74DULL;
            aOrbiterI = ((aWandererD + RotL64(aScatter, 3U)) + 0xF7A297CD1701C7DCULL) + aKeySpawnOrbiterAssignSaltC[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterJ = (aWandererB + RotL64(aPrevious, 13U)) + 0x979D983A3121310CULL;
            aOrbiterB = (aWandererJ + RotL64(aCross, 41U)) + 0xCBF61B7D7A715ECBULL;
