            aOrbiterE = (aWandererI + RotL64(aIngress, 53U)) + 0x4448F09D76A70EB8ULL;
            aOrbiterD = (aWandererF + RotL64(aCross, 24U)) + 0x7BB0D1E85DA3077BULL;
            //
            aOrbiterC = ((aOrbiterC + aOrbiterI) + 0x7633EDE7A63690A3ULL) + aKeySpawnOrbiterUpdateSaltD[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterC) ^ 0x3F8B4DB6C9052F96ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x8DE21776CDA86BABULL), 11U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x2A4B41B6D35EDF11ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0xBACFD22A3C7E721CULL;
            aOrbiterK = RotL64((aOrbiterK * 0x4F98797DC66C3DE5ULL), 29U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0xEBA2F5AA1311B1EDULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterJ) ^ 0xFA9CF6B09BE5773AULL;
            aOrbiterB = RotL64((aOrbiterB * 0x2826FCE689ABCEEBULL), 21U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0xC8C797D8A926293CULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0x67053AFC272276B8ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x1D2131F018B33371ULL), 47U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0x5DDEC471DD422707ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0x783D9752BA0D0187ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x69EA3A0E42657747ULL), 43U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0xF6A3DEC7862B944AULL;
