            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0xC20C0E39C69F51D6ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterA) ^ 0x98AEEFEC2E7AA941ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x5CC3C33B87A5558FULL), 57U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterE) + 0x376255C06F8FC97EULL) + aKeySpawnOrbiterUpdateSaltB[((aIndex + 18U)) & S_SALT1];
