            //
            aOrbiterE = ((aOrbiterE + aOrbiterC) + 0x725A7318D2D91C7DULL) + aKeySpawnOrbiterUpdateSaltE[((aIndex + 16U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0xBCC95208F80DE457ULL;
