            //
            aOrbiterH = ((aOrbiterH + aOrbiterK) + 0x28B40B7235E535BAULL) + aKeySpawnOrbiterUpdateSaltD[((aIndex + 11U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0xDB2E42C6463FAD25ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xBED9B21DA94F1111ULL), 37U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x74B45478DF1B8EBFULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0x1A9DD913EC71571FULL;
            aOrbiterA = RotL64((aOrbiterA * 0x8FAF2A7E080E6D79ULL), 41U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterD) + 0x3397A846198EB81FULL) + aKeySpawnOrbiterUpdateSaltC[((aIndex + 27U)) & S_SALT1];
